    "license": "CC BY-SA 4.0",
    "english": "Guilin is a city in the northeast of Guangxi, famous for its karst mountains and beautiful rivers. The Li River runs through it, and the green peaks on both banks look like a painting — people say 'Guilin's scenery is the finest under heaven'. Every year large numbers of tourists come to take a boat on the river, and Guilin has become one of China's best-known tourist cities.",
