    "english": "Chinese characters are the writing system of the Chinese language and the oldest script still widely used today. The earliest mature characters are the oracle-bone inscriptions of the Shang dynasty, carved on turtle shells and bones; from pictures they slowly developed into today's forms. Dictionaries collect more than 100,000 characters, but knowing 2,500–3,000 common ones is enough to read most newspapers. Characters are hard to learn at first, yet each one is like a small piece of history.",
