    "license": "CC BY-SA 4.0",
    "english": "The giant panda lives only in China and is one of the best-loved animals in the world. Its body is black and white, with black patches around its eyes, and it looks adorable. It lives in the mountain forests of Sichuan, Shaanxi and Gansu, and eats bamboo almost all day: half of its day goes to eating and the other half to sleeping. After years of protection there are about 2,700 pandas in the wild, and it is honoured as China's national treasure and the symbol of the WWF.",
