    "english": "Artificial intelligence is the ability of computer systems to perform tasks usually associated with human intelligence — learning, reasoning, problem-solving and decision-making. Founded as a discipline in 1956, the field went through cycles of optimism and disappointment until deep learning broke through after 2012. In the 2020s generative AI has drawn worldwide attention, along with debates over ethics and regulation.",
